head.script:

            scwin.onpageload = function() {
            };

            scwin.onpageunload = function() {

            };


	scwin.checkVal = function() {
		return !WebSquare.wUnit.getDomById("inputCalendar1_input").classList.contains("w2inputCalendar_focus");
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').focus()");

		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
